## 1. `core_network` Dio HTTP client — streaming support

**No.** `DioHttpClient` does **not** support streaming responses. The only `responseType` is `ResponseType.json` on `BaseOptions`. There is no `ResponseType.stream`, no per-request `responseType` override, and no `text/event-stream` handling. All methods buffer the full response into `HttpResponse.body` via `_toHttpResponse()`.

Full `post()` and related methods:

```64:168:/Users/jace/Documents/newapp/packages/core/core_network/lib/src/dio_http_client.dart
  @override
  Future<Result<HttpResponse>> get(
    String path, {
    Map<String, String>? headers,
    Map<String, dynamic>? queryParameters,
  }) =>
      _request('GET', path, headers: headers, queryParameters: queryParameters);

  @override
  Future<Result<HttpResponse>> post(
    String path, {
    Map<String, String>? headers,
    Object? body,
  }) => _request('POST', path, headers: headers, body: body);

  @override
  Future<Result<HttpResponse>> put(
    String path, {
    Map<String, String>? headers,
    Object? body,
  }) => _request('PUT', path, headers: headers, body: body);

  @override
  Future<Result<HttpResponse>> delete(
    String path, {
    Map<String, String>? headers,
  }) => _request('DELETE', path, headers: headers);

  @override
  Future<Result<HttpResponse>> upload(
    String path, {
    required List<HttpUploadFile> files,
    Map<String, String>? headers,
    Map<String, dynamic>? fields,
  }) async {
    try {
      final formData = FormData();
      if (fields != null) {
        formData.fields.addAll(
          fields.entries.map((entry) => MapEntry(entry.key, '${entry.value}')),
        );
      }
      for (final file in files) {
        formData.files.add(
          MapEntry(
            file.fieldName,
            MultipartFile.fromBytes(
              file.bytes,
              filename: file.filename,
              contentType: file.contentType == null
                  ? null
                  : DioMediaType.parse(file.contentType!),
            ),
          ),
        );
      }
      final response = await _dio.post<dynamic>(
        path,
        data: formData,
        options: Options(headers: headers),
      );
      return Result.success(_toHttpResponse(response));
    } on DioException catch (e) {
      return Result.failure(mapDioException(e));
    }
  }

  Future<Result<HttpResponse>> _request(
    String method,
    String path, {
    Map<String, String>? headers,
    Map<String, dynamic>? queryParameters,
    Object? body,
  }) async {
    try {
      final response = await _dio.request<dynamic>(
        path,
        data: body,
        queryParameters: queryParameters,
        options: Options(method: method, headers: headers),
      );
      return Result.success(_toHttpResponse(response));
    } on DioException catch (e) {
      return Result.failure(mapDioException(e));
    }
  }

  HttpResponse _toHttpResponse(Response<dynamic> response) {
    final responseHeaders = response.headers.map.map(
      (key, value) => MapEntry(key, value.join(', ')),
    );
    return HttpResponse(
      statusCode: response.statusCode ?? 0,
      body: _encodeBody(response.data),
      headers: responseHeaders,
    );
  }

  String _encodeBody(dynamic data) {
    if (data == null) return '';
    if (data is String) return data;
    if (data is Map || data is List) return jsonEncode(data);
    return data.toString();
  }
```

