## 4. `ObjectRecognitionSseParser.parse()`

Parses a **complete** `payload` string line-by-line (not incremental HTTP chunks). Full file:

```1:77:/Users/jace/Documents/newapp/packages/feature/ai/feature_glasses_object_recognition/lib/src/service/object_recognition_sse_parser.dart
import 'dart:convert';

import '../model/object_recognition_delta.dart';

class ObjectRecognitionSseParser {
  const ObjectRecognitionSseParser();

  Stream<ObjectRecognitionDelta> parse(String payload) async* {
    for (final line in const LineSplitter().convert(payload)) {
      final trimmed = line.trim();
      if (trimmed.isEmpty || trimmed.startsWith(':')) continue;
      final data = trimmed.startsWith('data:')
          ? trimmed.substring('data:'.length).trim()
          : trimmed;
      if (data == '[DONE]') {
        yield const ObjectRecognitionDelta.done();
        continue;
      }
      final event = _parseJson(data);
      if (event == null) continue;
      final delta = _toDelta(event);
      if (delta != null) yield delta;
    }
  }

  Map<String, dynamic>? _parseJson(String data) {
    final decoded = jsonDecode(data);
    if (decoded is Map<String, dynamic>) return decoded;
    return null;
  }

  ObjectRecognitionDelta? _toDelta(Map<String, dynamic> json) {
    final type = '${json['type'] ?? json['code'] ?? json['event'] ?? ''}';
    final data = json['data'] is Map<String, dynamic>
        ? json['data'] as Map<String, dynamic>
        : json;
    final sessionId =
        data['sessionId'] as String? ?? data['conversationId'] as String?;
    final languageId = data['languageId'] is int
        ? data['languageId'] as int
        : int.tryParse('${data['languageId'] ?? ''}');
    final state = '${data['state'] ?? data['status'] ?? ''}'.toUpperCase();

    if (type == '107' || data.containsKey('conversationId')) {
      return ObjectRecognitionDelta.done(
        sessionId: sessionId,
        languageId: languageId,
      );
    }
    if (type == '105' || state == 'END' || state == 'DONE') {
      return ObjectRecognitionDelta.done(
        sessionId: sessionId,
        languageId: languageId,
      );
    }
    if (state == 'ERROR' || type == 'error') {
      return ObjectRecognitionDelta.error(
        '${data['msg'] ?? data['message'] ?? 'Object recognition failed'}',
      );
    }
    final text =
        data['content'] ??
        data['text'] ??
        data['answer'] ??
        data['delta'] ??
        data['result'];
    if (text is String && text.isNotEmpty) {
      if (type == 'question') return ObjectRecognitionDelta.question(text);
      return ObjectRecognitionDelta.answerDelta(
        text,
        sessionId: sessionId,
        languageId: languageId,
      );
    }
    return null;
  }
}
```

