## 5. `ObjectRecognitionController` — `ask()`, `newRecognition()`, `refreshLast()`, `clearHistory()`

```89:209:/Users/jace/Documents/newapp/packages/feature/ai/feature_glasses_object_recognition/lib/src/viewmodel/object_recognition_controller.dart
  Future<void> ask(String question, {bool newFrame = false}) async {
    await _answerSub?.cancel();
    _lastQuestion = question;
    state = state.copyWith(clearError: true);

    var imageUrls = state.imageUrls;
    if (newFrame || imageUrls.isEmpty) {
      state = state.copyWith(status: ObjectRecognitionStatus.capturing);
      try {
        final frame = await ref.read(visualStreamProvider).captureFrame();
        _log('captured frame bytes=${frame.length}');
        if (_disposed) return;
        state = state.copyWith(status: ObjectRecognitionStatus.uploading);
        imageUrls = await ref
            .read(objectRecognitionServiceProvider)
            .uploadImages([frame]);
        _log('uploaded image urls=${imageUrls.length}');
      } catch (e) {
        if (_disposed) return;
        state = state.copyWith(
          status: ObjectRecognitionStatus.error,
          error: ObjectRecognitionError(
            kind: e is AppError &&
                    e.code == 'VISUAL_STREAM_CAPTURE_FAILED'
                ? ObjectRecognitionErrorKind.captureFailed
                : ObjectRecognitionErrorKind.uploadFailed,
            detail: _errorDetail(e),
          ),
        );
        _log('capture/upload failed: ${_errorDetail(e)}');
        return;
      }
    }

    final now = DateTime.now();
    final userMessage = ObjectRecognitionMessage(
      id: 'user-${now.microsecondsSinceEpoch}',
      role: ObjectRecognitionMessageRole.user,
      text: question,
      imageUrls: imageUrls,
      createdAt: now,
    );
    final assistantMessage = ObjectRecognitionMessage(
      id: 'assistant-${now.microsecondsSinceEpoch}',
      role: ObjectRecognitionMessageRole.assistant,
      text: '',
      createdAt: now,
      status: ObjectRecognitionMessageStatus.streaming,
    );
    state = state.copyWith(
      status: ObjectRecognitionStatus.answering,
      imageUrls: imageUrls,
      messages: [...state.messages, userMessage, assistantMessage],
    );

    final stream = ref.read(objectRecognitionServiceProvider).ask(
      question: question,
      imageUrls: imageUrls,
      sessionId: state.sessionId,
    );
    _answerSub = stream.listen(
      (delta) => _handleAnswerDelta(delta, assistantMessage.id),
      onError: (Object error) => _handleAnswerError(error, assistantMessage.id),
      onDone: () => _finalizeAnswer(assistantMessage.id),
    );
  }

  Future<void> refreshLast() async {
    final question = _lastQuestion;
    if (question == null || question.isEmpty || state.isBusy) return;
    await ask(question);
  }

  Future<void> newRecognition() async {
    final question = state.inputText.trim().isEmpty ? '这是什么？' : state.inputText.trim();
    state = state.copyWith(inputText: '');
    await ask(question, newFrame: true);
  }

  // ... cancelAnswer, toggleSpeak ...

  Future<void> clearHistory() async {
    await ref.read(objectRecognitionHistoryRepositoryProvider).clear();
    state = state.copyWith(
      messages: const [],
      imageUrls: const [],
      sessionId: null,
    );
  }
```

**State machine notes:**

- **`imageUrls`**: Reused from `state.imageUrls` unless `newFrame == true` or `imageUrls.isEmpty` → capture + upload new frame. After success, stored back via `state.copyWith(imageUrls: imageUrls)`.
- **`sessionId`**: Passed into `ask()` from `state.sessionId`. Updated in `_handleAnswerDelta` on `answerDelta` and `done` deltas (`state.copyWith(sessionId: delta.sessionId)`). Cleared in `clearHistory()`.
- **Transitions in `ask()`**: `clearError` → (`capturing` → `uploading` if new frame) → `answering` → (via deltas) `previewing` on finalize, or `error` on failure.
- **`refreshLast()`**: Re-asks `_lastQuestion` without `newFrame` → reuses existing `imageUrls` and `sessionId`.
- **`newRecognition()`**: Forces `newFrame: true` → new capture/upload, new `imageUrls`; `sessionId` still passed through unless cleared.

Delta handling for `sessionId`:

```233:256:/Users/jace/Documents/newapp/packages/feature/ai/feature_glasses_object_recognition/lib/src/viewmodel/object_recognition_controller.dart
  void _handleAnswerDelta(ObjectRecognitionDelta delta, String assistantId) {
    if (_disposed) return;
    switch (delta.kind) {
      case ObjectRecognitionDeltaKind.question:
        break;
      case ObjectRecognitionDeltaKind.answerDelta:
        final current = state.messages
            .where((message) => message.id == assistantId)
            .firstOrNull;
        if (current == null) return;
        _replaceMessage(
          current.copyWith(
            text: current.text + delta.text,
            languageId: delta.languageId,
          ),
        );
        state = state.copyWith(sessionId: delta.sessionId);
      case ObjectRecognitionDeltaKind.done:
        state = state.copyWith(sessionId: delta.sessionId);
        _finalizeAnswer(assistantId, languageId: delta.languageId);
      case ObjectRecognitionDeltaKind.error:
        _handleAnswerError(delta.errorMessage ?? 'Object recognition failed', assistantId);
    }
  }
```

