enum VisualStreamStatus {
  idle,
  connecting,
  previewing,
  disconnected,
  error,
}

class VisualStreamEvent {
  const VisualStreamEvent({
    required this.status,
    this.message,
    this.errorCode,
  });

  final VisualStreamStatus status;
  final String? message;
  final String? errorCode;

  const VisualStreamEvent.idle() : this(status: VisualStreamStatus.idle);

  const VisualStreamEvent.connecting()
    : this(status: VisualStreamStatus.connecting);

  const VisualStreamEvent.previewing()
    : this(status: VisualStreamStatus.previewing);

  const VisualStreamEvent.disconnected()
    : this(status: VisualStreamStatus.disconnected);

  const VisualStreamEvent.error({String? message, String? errorCode})
    : this(
        status: VisualStreamStatus.error,
        message: message,
        errorCode: errorCode,
      );
}
