## 7. `media_kit_visual_stream.dart` — complete file

```1:111:/Users/jace/Documents/newapp/packages/core/core_visual_stream/lib/src/media_kit_visual_stream.dart
import 'dart:async';
import 'dart:typed_data';

import 'package:core_base/core_base.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';
import 'package:media_kit/media_kit.dart';
import 'package:media_kit_video/media_kit_video.dart';

import 'visual_stream.dart';
import 'visual_stream_config.dart';
import 'visual_stream_event.dart';

class MediaKitVisualStream implements VisualStream {
  MediaKitVisualStream({Player? player})
    : _player = player ?? Player(),
      _ownsPlayer = player == null {
    _controller = VideoController(_player);
  }

  final Player _player;
  final bool _ownsPlayer;
  late final VideoController _controller;
  final _events = StreamController<VisualStreamEvent>.broadcast();
  StreamSubscription<bool>? _playingSub;
  StreamSubscription<Object?>? _errorSub;

  @override
  Stream<VisualStreamEvent> get events => _events.stream;

  @override
  Future<void> connect(VisualStreamConfig config) async {
    final uri = config.uri;
    if (uri == null) {
      throw const AppError(
        code: 'VISUAL_STREAM_MISSING_URI',
        message: 'MediaKit visual stream requires a URL.',
      );
    }
    debugPrint(
      '[VisualStream][MediaKit] connect uri=${_redactUri(uri)} '
      'headers=${config.headers.keys.toList()} timeout=${config.connectTimeout.inSeconds}s',
    );
    _events.add(const VisualStreamEvent.connecting());
    _playingSub ??= _player.stream.playing.listen((playing) {
      if (playing) {
        debugPrint('[VisualStream][MediaKit] previewing');
        _events.add(const VisualStreamEvent.previewing());
      }
    });
    _errorSub ??= _player.stream.error.listen((error) {
      debugPrint('[VisualStream][MediaKit] playback error: $error');
      _events.add(
        VisualStreamEvent.error(
          errorCode: 'VISUAL_STREAM_PLAYBACK_FAILED',
          message: error.toString(),
        ),
      );
    });

    await _player
        .open(
          Media(
            uri.toString(),
            httpHeaders: config.headers.isEmpty ? null : config.headers,
          ),
        )
        .timeout(config.connectTimeout);
    debugPrint('[VisualStream][MediaKit] open completed');
  }

  @override
  Future<void> disconnect() async {
    debugPrint('[VisualStream][MediaKit] disconnect');
    await _player.stop();
    _events.add(const VisualStreamEvent.disconnected());
  }

  @override
  Widget buildPreview() {
    return Video(controller: _controller, fit: BoxFit.cover);
  }

  @override
  Future<Uint8List> captureFrame() async {
    final bytes = await _player.screenshot(format: 'image/png');
    if (bytes == null || bytes.isEmpty) {
      debugPrint('[VisualStream][MediaKit] captureFrame failed: empty screenshot');
      throw const AppError(
        code: 'VISUAL_STREAM_CAPTURE_FAILED',
        message: 'Unable to capture a frame from the visual stream.',
      );
    }
    debugPrint('[VisualStream][MediaKit] captureFrame bytes=${bytes.length}');
    return bytes;
  }

  Future<void> dispose() async {
    await _playingSub?.cancel();
    await _errorSub?.cancel();
    await _events.close();
    if (_ownsPlayer) {
      await _player.dispose();
    }
  }
}

String _redactUri(Uri uri) {
  if (uri.userInfo.isEmpty) return uri.toString();
  return uri.replace(userInfo: '<redacted>').toString();
}
```

**Buffering/error emission:** There is no explicit buffering state. Events emitted:
- `connecting` on `connect()` start
- `previewing` when `_player.stream.playing` becomes `true`
- `error` (`VISUAL_STREAM_PLAYBACK_FAILED`) on `_player.stream.error`
- `disconnected` on `disconnect()`
- `captureFrame()` throws `VISUAL_STREAM_CAPTURE_FAILED` if screenshot is null/empty (not emitted as a `VisualStreamEvent`)

---

### Cross-cutting conclusion

The object-recognition "stream" is **post-hoc**: HTTP returns a full body string, then `ObjectRecognitionSseParser` walks it line-by-line. True incremental SSE over `text/event-stream` would require extending `HttpClient`/`DioHttpClient` with `ResponseType.stream` (or equivalent) and piping chunks into the parser as they arrive.
